type Category = 'Stationery' | 'Printer' | 'Kitchen' | 'Cleaning' | 'Tech';
type Unit = 'each' | 'box' | 'ream' | 'pack';
type MovementReason = 'Issued' | 'Received' | 'Damaged' | 'Adjustment' | 'Stocktake';
type PurchaseRequestStatus = 'Open' | 'Approved' | 'Ordered' | 'Received' | 'Cancelled';

interface Item {
  id: string;
  name: string;
  category: Category;
  unit: Unit;
  currentQty: number;
  reorderLevel: number;
  targetQty: number;
  location: string;
  active: boolean;
  unitCost?: number;
}

interface Movement {
  id: string;
  itemId: string;
  delta: number;
  reason: MovementReason;
  actor: string;
  timestamp: string;
  note: string;
  resultingQty: number;
}

interface PurchaseRequest {
  id: string;
  itemId: string;
  requestedQty: number;
  status: PurchaseRequestStatus;
  raisedBy: string;
  decisionNote: string;
}

interface ItemRow {
  id: string;
  name: string;
  category: Category;
  unit: Unit;
  currentQty: number;
  reorderLevel: number;
  status: string;
  location: string;
  active: boolean;
}

interface ItemListResult {
  ok: boolean;
  rows: ItemRow[];
  error: string;
}

interface StockItemResult {
  ok: boolean;
  item: Item | null;
  movements: Movement[];
  requests: PurchaseRequest[];
  error: string;
}

interface VarianceRow {
  itemId: string;
  name: string;
  delta: number;
  direction: string;
}

interface StocktakeResult {
  ok: boolean;
  variance: VarianceRow[];
  movements: Movement[];
  items: Item[];
  error: string;
}

interface DashboardResult {
  totalItems: number;
  belowReorder: number;
  openPurchaseRequests: number;
  totalValuePence: number;
  valueDisplay: string;
}

interface VerifyRow {
  itemId: string;
  name: string;
  storedQty: number;
  reconstructedQty: number;
  matches: boolean;
}

interface VerifyResult {
  ok: boolean;
  rows: VerifyRow[];
  drifted: number;
}

interface InventoryState {
  items: Item[];
  movements: Movement[];
  requests: PurchaseRequest[];
  seq: number;
}

interface ClockLike {
  nowIso: string;
}

/**
 * Create a fresh in-memory inventory state with deterministic counters.
 *
 * @returns {InventoryState} an empty inventory state.
 */
function createState(): InventoryState {
  return { items: [], movements: [], requests: [], seq: 0 };
}

/**
 * Deterministically build the next identifier from the state sequence.
 *
 * @param {InventoryState} state - the inventory state.
 * @param {string} prefix - a short prefix for the identifier.
 * @returns {string} a stable identifier string.
 */
function nextId(state: InventoryState, prefix: string): string {
  state.seq = state.seq + 1;
  let n: number = state.seq;
  let digits: string = '';
  while (n > 0) {
    const d: number = n % 10;
    digits = String(d) + digits;
    n = Math.floor(n / 10);
  }
  while (digits.length < 8) {
    digits = '0' + digits;
  }
  return prefix + '-' + digits;
}

/**
 * Deterministically derive an ISO timestamp from a supplied base time and offset.
 *
 * @param {InventoryState} state - the inventory state.
 * @param {string} baseIso - the base ISO timestamp (usually the wall clock).
 * @param {number} offsetMs - the millisecond offset for this record.
 * @returns {string} an ISO timestamp string.
 */
function stamp(state: InventoryState, baseIso: string, offsetMs: number): string {
  const base: number = Date.parse(baseIso);
  const baseValue: number = isNaN(base) ? 0 : base;
  const parts: number[] = [baseValue + offsetMs];
  return new Date(parts[0]).toISOString();
}

/**
 * Determine whether a value is a non-negative integer quantity.
 *
 * @param {unknown} value - the value to check.
 * @returns {boolean} true when the value is a finite non-negative integer.
 */
function isNonNegativeInteger(value: unknown): boolean {
  if (typeof value !== 'number') {
    return false;
  }
  if (!isFinite(value)) {
    return false;
  }
  if (Math.floor(value) !== value) {
    return false;
  }
  return value >= 0;
}

/**
 * Locate an item by id and reject unknown or inactive items on the failure path.
 *
 * @param {Item[]} items - the stored items.
 * @param {string} itemId - the item identifier.
 * @returns {Item | null} the item when found, otherwise null.
 */
function findItem(items: Item[], itemId: string): Item | null {
  let i: number = 0;
  while (i < items.length) {
    const candidate: Item = items[i];
    if (candidate.id === itemId) {
      return candidate;
    }
    i = i + 1;
  }
  return null;
}

/**
 * Compute the colour-coded stock status label for an item row.
 *
 * @param {Item} item - the item to classify.
 * @param {number} threshold - the variance threshold in use.
 * @returns {string} one of 'out', 'low', 'ok' or 'inactive'.
 */
function statusFor(item: Item, threshold: number): string {
  if (!item.active) {
    return 'inactive';
  }
  if (item.currentQty <= 0) {
    return 'out';
  }
  if (item.currentQty <= item.reorderLevel) {
    return 'low';
  }
  if (threshold > 0 && item.currentQty <= item.reorderLevel + threshold) {
    return 'warn';
  }
  return 'ok';
}

/**
 * Determine whether an item currently needs reordering.
 *
 * @param {Item} item - the item to test.
 * @returns {boolean} true when the item is active and at or below its reorder level.
 */
function needsReorder(item: Item): boolean {
  return item.active === true && item.currentQty <= item.reorderLevel;
}

/**
 * Append a movement to the log using a deterministic id and timestamp.
 *
 * @param {InventoryState} state - the inventory state.
 * @param {string} itemId - the item identifier.
 * @param {number} delta - the signed quantity change.
 * @param {MovementReason} reason - the movement reason.
 * @param {string} actor - who performed the movement.
 * @param {string} note - a free-text note.
 * @param {number} resultingQty - the quantity after the movement.
 * @param {string} baseIso - the base ISO timestamp.
 * @returns {Movement} the appended movement.
 */
function appendMovement(state: InventoryState, itemId: string, delta: number, reason: MovementReason, actor: string, note: string, resultingQty: number, baseIso: string): Movement {
  const movement: Movement = {
    id: nextId(state, 'mv'),
    itemId: itemId,
    delta: delta,
    reason: reason,
    actor: actor,
    timestamp: stamp(state, baseIso, state.seq),
    note: note,
    resultingQty: resultingQty
  };
  state.movements.push(movement);
  return movement;
}

/**
 * Whether a purchase request is still open for receiving purposes.
 *
 * @param {PurchaseRequestStatus} s - the request status.
 * @returns {boolean} true for Open, Approved or Ordered.
 */
function isOpenRequestStatus(s: PurchaseRequestStatus): boolean {
  return s === 'Open' || s === 'Approved' || s === 'Ordered';
}

/**
 * Create a new item in the catalogue.
 *
 * @param {InventoryState} state - the inventory state.
 * @param {{ name: string; category: Category; unit: Unit; currentQty: number; reorderLevel: number; targetQty: number; location: string; active: boolean; unitCost?: number }} fields - the item fields.
 * @returns {Item} the stored item.
 */
function createItem(state: InventoryState, fields: { name: string; category: Category; unit: Unit; currentQty: number; reorderLevel: number; targetQty: number; location: string; active: boolean; unitCost?: number }): Item {
  const item: Item = {
    id: nextId(state, 'it'),
    name: fields.name,
    category: fields.category,
    unit: fields.unit,
    currentQty: fields.currentQty,
    reorderLevel: fields.reorderLevel,
    targetQty: fields.targetQty,
    location: fields.location,
    active: fields.active
  };
  if (typeof fields.unitCost === 'number') {
    item.unitCost = fields.unitCost;
  }
  state.items.push(item);
  return item;
}

/**
 * Filter, sort, and project items for accessible list rendering.
 *
 * @param {Item[]} items - the stored items.
 * @param {{ search?: string; category?: Category | null; needsReorder?: boolean; sortBy?: string }} options - list options.
 * @returns {ItemListResult} matching rows with qty, reorder level, status and location.
 */
function listItems(items: Item[], options: { search?: string; category?: Category | null; needsReorder?: boolean; sortBy?: string }): ItemListResult {
  const search: string = typeof options.search === 'string' ? options.search.trim().toLowerCase() : '';
  const category: Category | null = options.category === undefined ? null : options.category;
  const reorderOnly: boolean = options.needsReorder === true;
  const sortBy: string = typeof options.sortBy === 'string' ? options.sortBy : 'name';
  const rows: ItemRow[] = [];
  let i: number = 0;
  while (i < items.length) {
    const item: Item = items[i];
    let keep: boolean = true;
    if (category !== null && item.category !== category) {
      keep = false;
    }
    if (reorderOnly && !needsReorder(item)) {
      keep = false;
    }
    if (search.length > 0 && item.name.toLowerCase().indexOf(search) === -1) {
      keep = false;
    }
    if (keep) {
      const row: ItemRow = {
        id: item.id,
        name: item.name,
        category: item.category,
        unit: item.unit,
        currentQty: item.currentQty,
        reorderLevel: item.reorderLevel,
        status: statusFor(item, 0),
        location: item.location,
        active: item.active
      };
      rows.push(row);
    }
    i = i + 1;
  }
  rows.sort(function (a: ItemRow, b: ItemRow): number {
    if (sortBy === 'qty') {
      if (a.currentQty !== b.currentQty) {
        return a.currentQty - b.currentQty;
      }
      return a.name < b.name ? -1 : 1;
    }
    if (sortBy === 'category') {
      if (a.category !== b.category) {
        return a.category < b.category ? -1 : 1;
      }
      return a.name < b.name ? -1 : 1;
    }
    if (a.name !== b.name) {
      return a.name < b.name ? -1 : 1;
    }
    return 0;
  });
  return { ok: true, rows: rows, error: '' };
}

/**
 * Issue an item to a member of staff.
 *
 * @param {InventoryState} state - the inventory state.
 * @param {string} itemId - the item identifier.
 * @param {number} qty - the quantity to issue.
 * @param {string} actor - who is taking the item.
 * @param {string} baseIso - the base ISO timestamp.
 * @returns {StockItemResult} the updated item and movement, or a failure.
 */
function issueItem(state: InventoryState, itemId: string, qty: number, actor: string, baseIso: string): StockItemResult {
  const item: Item | null = findItem(state.items, itemId);
  if (item === null) {
    return { ok: false, item: null, movements: [], requests: [], error: 'not-found' };
  }
  if (!item.active) {
    return { ok: false, item: null, movements: [], requests: [], error: 'inactive' };
  }
  if (!isNonNegativeInteger(qty)) {
    return { ok: false, item: null, movements: [], requests: [], error: 'invalid-quantity' };
  }
  if (qty > item.currentQty) {
    const shortfall: number = qty - item.currentQty;
    return { ok: false, item: null, movements: [], requests: [], error: 'shortfall ' + String(shortfall) };
  }
  item.currentQty = item.currentQty - qty;
  const movement: Movement = appendMovement(state, item.id, -qty, 'Issued', actor, '', item.currentQty, baseIso);
  return { ok: true, item: item, movements: [movement], requests: [], error: '' };
}

/**
 * Receive a delivery of stock, transitioning any open request to Received.
 *
 * @param {InventoryState} state - the inventory state.
 * @param {string} itemId - the item identifier.
 * @param {number} qty - the quantity received.
 * @param {string} actor - who received the delivery.
 * @param {string} baseIso - the base ISO timestamp.
 * @returns {StockItemResult} the updated item, movement and requests, or a failure.
 */
function receiveStock(state: InventoryState, itemId: string, qty: number, actor: string, baseIso: string): StockItemResult {
  const item: Item | null = findItem(state.items, itemId);
  if (item === null) {
    return { ok: false, item: null, movements: [], requests: [], error: 'not-found' };
  }
  if (!item.active) {
    return { ok: false, item: null, movements: [], requests: [], error: 'inactive' };
  }
  if (!isNonNegativeInteger(qty)) {
    return { ok: false, item: null, movements: [], requests: [], error: 'invalid-quantity' };
  }
  item.currentQty = item.currentQty + qty;
  const movement: Movement = appendMovement(state, item.id, qty, 'Received', actor, '', item.currentQty, baseIso);
  const touched: PurchaseRequest[] = [];
  let i: number = 0;
  while (i < state.requests.length) {
    const request: PurchaseRequest = state.requests[i];
    if (request.itemId === item.id && isOpenRequestStatus(request.status)) {
      request.status = 'Received';
      touched.push(request);
    }
    i = i + 1;
  }
  return { ok: true, item: item, movements: [movement], requests: touched, error: '' };
}

/**
 * Record damaged stock, decrementing the quantity like an issue.
 *
 * @param {InventoryState} state - the inventory state.
 * @param {string} itemId - the item identifier.
 * @param {number} qty - the damaged quantity.
 * @param {string} actor - who recorded the damage.
 * @param {string} baseIso - the base ISO timestamp.
 * @returns {StockItemResult} the updated item and movement, or a failure.
 */
function recordDamaged(state: InventoryState, itemId: string, qty: number, actor: string, baseIso: string): StockItemResult {
  const item: Item | null = findItem(state.items, itemId);
  if (item === null) {
    return { ok: false, item: null, movements: [], requests: [], error: 'not-found' };
  }
  if (!item.active) {
    return { ok: false, item: null, movements: [], requests: [], error: 'inactive' };
  }
  if (!isNonNegativeInteger(qty)) {
    return { ok: false, item: null, movements: [], requests: [], error: 'invalid-quantity' };
  }
  if (qty > item.currentQty) {
    const shortfall: number = qty - item.currentQty;
    return { ok: false, item: null, movements: [], requests: [], error: 'shortfall ' + String(shortfall) };
  }
  item.currentQty = item.currentQty - qty;
  const movement: Movement = appendMovement(state, item.id, -qty, 'Damaged', actor, '', item.currentQty, baseIso);
  return { ok: true, item: item, movements: [movement], requests: [], error: '' };
}

/**
 * Record a counted adjustment, requiring a non-empty note and writing a movement.
 *
 * @param {InventoryState} state - the inventory state.
 * @param {string} itemId - the item identifier.
 * @param {number} countedQty - the counted quantity.
 * @param {string} actor - who counted.
 * @param {string} note - the required explanation note.
 * @param {string} baseIso - the base ISO timestamp.
 * @returns {StockItemResult} the updated item and movement, or a failure.
 */
function recordAdjustment(state: InventoryState, itemId: string, countedQty: number, actor: string, note: string, baseIso: string): StockItemResult {
  const item: Item | null = findItem(state.items, itemId);
  if (item === null) {
    return { ok: false, item: null, movements: [], requests: [], error: 'not-found' };
  }
  if (!item.active) {
    return { ok: false, item: null, movements: [], requests: [], error: 'inactive' };
  }
  const trimmed: string = typeof note === 'string' ? note.trim() : '';
  if (trimmed.length === 0) {
    return { ok: false, item: null, movements: [], requests: [], error: 'note-required' };
  }
  if (!isNonNegativeInteger(countedQty)) {
    return { ok: false, item: null, movements: [], requests: [], error: 'invalid-quantity' };
  }
  const delta: number = countedQty - item.currentQty;
  item.currentQty = countedQty;
  const movement: Movement = appendMovement(state, item.id, delta, 'Adjustment', actor, trimmed, item.currentQty, baseIso);
  return { ok: true, item: item, movements: [movement], requests: [], error: '' };
}

/**
 * Raise a purchase request for an item at or below its reorder level.
 *
 * @param {InventoryState} state - the inventory state.
 * @param {string} itemId - the item identifier.
 * @param {string} actor - who raised the request.
 * @param {string} baseIso - the base ISO timestamp.
 * @returns {StockItemResult} the created request, or a failure.
 */
function raisePurchaseRequest(state: InventoryState, itemId: string, actor: string, baseIso: string): StockItemResult {
  const item: Item | null = findItem(state.items, itemId);
  if (item === null) {
    return { ok: false, item: null, movements: [], requests: [], error: 'not-found' };
  }
  if (!needsReorder(item)) {
    return { ok: false, item: null, movements: [], requests: [], error: 'above-reorder-level' };
  }
  const suggested: number = Math.max(0, item.targetQty - item.currentQty);
  const request: PurchaseRequest = {
    id: nextId(state, 'pr'),
    itemId: item.id,
    requestedQty: suggested,
    status: 'Open',
    raisedBy: actor,
    decisionNote: ''
  };
  state.requests.push(request);
  const stampIso: string = stamp(state, baseIso, state.seq);
  const noteMovement: Movement = appendMovement(state, item.id, 0, 'Adjustment', actor, 'request-raised ' + stampIso, item.currentQty, baseIso);
  return { ok: true, item: item, movements: [noteMovement], requests: [request], error: '' };
}

/**
 * Transition a purchase request along the permitted status graph.
 *
 * @param {InventoryState} state - the inventory state.
 * @param {string} requestId - the request identifier.
 * @param {PurchaseRequestStatus} next - the attempted next status.
 * @param {string} note - the decision note.
 * @returns {StockItemResult} the updated request, or a failure.
 */
function transitionRequest(state: InventoryState, requestId: string, next: PurchaseRequestStatus, note: string): StockItemResult {
  let found: PurchaseRequest | null = null;
  let i: number = 0;
  while (i < state.requests.length) {
    const candidate: PurchaseRequest = state.requests[i];
    if (candidate.id === requestId) {
      found = candidate;
    }
    i = i + 1;
  }
  if (found === null) {
    return { ok: false, item: null, movements: [], requests: [], error: 'request-not-found' };
  }
  const current: PurchaseRequestStatus = found.status;
  const legal: boolean =
    (current === 'Open' && (next === 'Approved' || next === 'Cancelled' || next === 'Ordered')) ||
    (current === 'Approved' && (next === 'Ordered' || next === 'Cancelled')) ||
    (current === 'Ordered' && (next === 'Received' || next === 'Cancelled')) ||
    (current === 'Open' && next === 'Received');
  if (!legal) {
    return { ok: false, item: null, movements: [], requests: [], error: 'illegal-transition from ' + current + ' to ' + next };
  }
  found.status = next;
  found.decisionNote = typeof note === 'string' ? note : '';
  return { ok: true, item: null, movements: [], requests: [found], error: '' };
}

/**
 * Approve a purchase request currently in Open status.
 *
 * @param {InventoryState} state - the inventory state.
 * @param {string} requestId - the request identifier.
 * @param {string} note - the decision note.
 * @returns {StockItemResult} the approved request, or a failure.
 */
function approveRequest(state: InventoryState, requestId: string, note: string): StockItemResult {
  return transitionRequest(state, requestId, 'Approved', note);
}

/**
 * Order a purchase request currently in Approved status.
 *
 * @param {InventoryState} state - the inventory state.
 * @param {string} requestId - the request identifier.
 * @param {string} note - the decision note.
 * @returns {StockItemResult} the ordered request, or a failure.
 */
function orderRequest(state: InventoryState, requestId: string, note: string): StockItemResult {
